#include <regex>
#include <string>
#include <string_view>
#include <cwctype>
#include <cassert>
#include <iostream>
struct CFiltering{static std::wstring NormalizePathRegex(std::wstring_view);static std::wregex CompilePattern(const std::wstring&,bool,bool);};
static bool HasUnescapedTrailingDollar(const std::wstring_view pattern)
{
    if (pattern.empty() || pattern.back() != L'$') return false;

    size_t slashCount = 0;
    for (size_t i = pattern.size() - 1; i > 0 && pattern[i - 1] == L'\\'; --i)
    {
        ++slashCount;
    }
    return slashCount % 2 == 0;
}

static std::wstring MatchDirectoryAndDescendants(std::wstring pattern)
{
    if (HasUnescapedTrailingDollar(pattern)) pattern.pop_back();
    return L"(?:" + pattern + L")(?:\\\\.*)?";
}
std::wstring GlobToRegex(const std::wstring& glob, const bool useAnchors)
{
    static const std::wregex escapePattern(LR"([.\\+^$|()[\]{}])", std::regex_constants::optimize);
    static const std::wregex starPattern(LR"(\*+)", std::regex_constants::optimize);
    static const std::wregex questionPattern(LR"(\?)", std::regex_constants::optimize);

    std::wstring regex = glob;
    regex = std::regex_replace(regex, escapePattern, LR"(\$&)");
    regex = std::regex_replace(regex, starPattern, LR"([^\\/:]*)");
    regex = std::regex_replace(regex, questionPattern, LR"([^\\/:])");

    return useAnchors ? (L"^" + regex + L"$") : regex;
}
std::wstring CFiltering::NormalizePathRegex(const std::wstring_view pattern)
{
    constexpr std::wstring_view preservedEscapes = LR"(\.+*?()[]{}^$|/bBdDsSwWfnrtv0cux123456789)";
    std::wstring result;
    result.reserve(pattern.size());
    for (size_t i = 0; i < pattern.size(); ++i)
    {
        if (pattern[i] == L'\\' &&
            (i + 1 >= pattern.size() || (!preservedEscapes.contains(pattern[i + 1]) &&
                !iswspace(pattern[i + 1]) && !iswpunct(pattern[i + 1]))))
        {
            result += L"\\\\";
        }
        else if (pattern[i] == L'\\')
        {
            result.push_back(pattern[i]);
            result.push_back(pattern[++i]);
        }
        else
        {
            result.push_back(pattern[i]);
        }
    }
    return result;
}
std::wregex CFiltering::CompilePattern(const std::wstring& pattern, const bool useRegex, const bool pathFilter)
{
    // In regex mode, normalize lone backslashes in path-based patterns so
    // users can type V:\Folder without having to escape the path separators.
    const std::wstring normalized = useRegex && pathFilter ? NormalizePathRegex(pattern) : pattern;

    // Directory filters apply to the directory itself and everything below it.
    std::wstring expression = useRegex ? normalized : GlobToRegex(normalized, false);
    if (pathFilter) expression = MatchDirectoryAndDescendants(std::move(expression));
    return std::wregex(expression, std::regex_constants::icase | std::regex_constants::optimize);
}

int main(){auto glob=CFiltering::CompilePattern(L"*.txt",false,false);assert(std::regex_search(std::wstring(L"notes.txt"),glob));assert(!std::regex_search(std::wstring(L"photo.png"),glob));bool rejected=false;try{CFiltering::CompilePattern(L"*.txt",true,false);}catch(const std::regex_error&){rejected=true;}assert(rejected);auto regex=CFiltering::CompilePattern(L".*\\.txt$",true,false);assert(std::regex_search(std::wstring(L"notes.txt"),regex));assert(!std::regex_search(std::wstring(L"photo.png"),regex));std::cout<<"5 assertions passed: glob exclusion fails regex compilation; regex control matches\n";}
